func (s *GameDataState) ClearDirty() {
	diff.ClearDirty(s.dirty[:])
	s.scalarsOperation = 0
	if s.scalars != nil {
		s.scalars.ClearDirty()
	}
	s.profileOperation = 0
	if s.profile != nil {
		s.profile.ClearDirty()
	}
	s.itemsChanges.ClearDirty()
	s.currenciesChanges.ClearDirty()
	s.snapshotsChanges.ClearDirty()
	s.featureFlagsChanges.ClearDirty()
	s.checkpointsChanges.ClearDirty()
	s.labelsChanges.ClearDirty()
	s.packetsChanges.ClearDirty()
	s.lineupChanges.ClearDirty()
	s.qualitiesChanges.ClearDirty()
	s.wideOperation = 0
	if s.wide != nil {
		s.wide.ClearDirty()
	}
}

